    BEGIN
        SELECT [dbo].[tblMobileDeviceProfile].[MobileDeviceProfileGuid],[dbo].[tblMobileDeviceProfile].[SiteGuid],[dbo].[tblMobileDeviceProfile].[ProfileID],[dbo].[tblMobileDeviceProfile].[Description],[dbo].[tblMobileDeviceProfile].[ShowProductScreen],[dbo].[tblMobileDeviceProfile].[GenerateTicketNumber],[dbo].[tblMobileDeviceProfile].[ShowOperatorFieldInFlightList],[dbo].[tblMobileDeviceProfile].[UseDefaultPrinter],[dbo].[tblMobileDeviceProfile].[DefaultPrinter],[dbo].[tblMobileDeviceProfile].[AdminPassword],[dbo].[tblMobileDeviceProfile].[ShutdownHotKey],[dbo].[tblMobileDeviceProfile].[PrinterCOMPort],[dbo].[tblMobileDeviceProfile].[SearchType],[dbo].[tblMobileDeviceProfile].[LoggingOption],[dbo].[tblMobileDeviceProfile].[AllowableFailedLoginAttempts],[dbo].[tblMobileDeviceProfile].[FuelDistributionPrecision],[dbo].[tblMobileDeviceProfile].[MakeDefaultProfile],[dbo].[tblMobileDeviceProfile].[VehicleID],[dbo].[tblMobileDeviceProfile].[MonitorScreenTransitionTiming],[dbo].[tblMobileDeviceProfile].[BypassFsrCheckOnScreenTrans],[dbo].[tblMobileDeviceProfile].[ShowFuelUpdateCheckStatusWin],[dbo].[tblMobileDeviceProfile].[RTDTemperatureRangeMin],[dbo].[tblMobileDeviceProfile].[RTDTemperatureRangeMax],[dbo].[tblMobileDeviceProfile].[DefaultTemperature],[dbo].[tblMobileDeviceProfile].[StrictUserValidation],[dbo].[tblMobileDeviceProfile].[VerifyFuelingEquipment],[dbo].[tblMobileDeviceProfile].[AllowEditRequiredFuelLoad],[dbo].[tblMobileDeviceProfile].[AllowBackAfterArrivalScreen],[dbo].[tblMobileDeviceProfile].[AllowBackAfterTicketPrinted],[dbo].[tblMobileDeviceProfile].[RequirePrint],[dbo].[tblMobileDeviceProfile].[TotalFuelLoadCheck],[dbo].[tblMobileDeviceProfile].[VolumetricThresholdValidation],[dbo].[tblMobileDeviceProfile].[ValidateShipNumber],[dbo].[tblMobileDeviceProfile].[AllowVTOModification],[dbo].[tblMobileDeviceProfile].[AllowFlightGateModification],[dbo].[tblMobileDeviceProfile].[TankPositionBalanceVerification],[dbo].[tblMobileDeviceProfile].[TankPositionBal