ileDeviceProfile].[EAAllowAircraftTypeModification],[dbo].[tblMobileDeviceProfile].[EAAllowDestinationModification],[dbo].[tblMobileDeviceProfile].[EADestination],[dbo].[tblMobileDeviceProfile].[EATicketPrinting],[dbo].[tblMobileDeviceProfile].[EAAircraftType],[dbo].[tblMobileDeviceProfile].[EAShipNumber],[dbo].[tblMobileDeviceProfile].[EAGateNumber],[dbo].[tblMobileDeviceProfile].[EAMeterTotal],[dbo].[tblMobileDeviceProfile].[EAVolumePumped],[dbo].[tblMobileDeviceProfile].[EATankCapacity],[dbo].[tblMobileDeviceProfile].[EquipmentType],[dbo].[tblMobileDeviceProfile].[ForeignKeyToMapEquipment],[dbo].[tblMobileDeviceProfile].[IssueTransaction],[dbo].[tblMobileDeviceProfile].[DefuelTransaction],[dbo].[tblMobileDeviceProfile].[RotationTransaction],[dbo].[tblMobileDeviceProfile].[MeterCloseout],[dbo].[tblMobileDeviceProfile].[DeIceTransaction],[dbo].[tblMobileDeviceProfile].[GSETransaction],[dbo].[tblMobileDeviceProfile].[ManualConsumer],[dbo].[tblMobileDeviceProfile].[ManualVendor],[dbo].[tblMobileDeviceProfile].[ManualShipper],[dbo].[tblMobileDeviceProfile].[ManualManager],[dbo].[tblMobileDeviceProfile].[ManualSupplier],[dbo].[tblMobileDeviceProfile].[ManualBillTo],[dbo].[tblMobileDeviceProfile].[ManualProduct],[dbo].[tblMobileDeviceProfile].[CloseoutConsumer],[dbo].[tblMobileDeviceProfile].[CloseoutOwner],[dbo].[tblMobileDeviceProfile].[CloseoutVendor],[dbo].[tblMobileDeviceProfile].[ManualStationID],[dbo].[tblMobileDeviceProfile].[InhibitOverridingTemperature],[dbo].[tblMobileDeviceProfile].[ManualTemperature],[dbo].[tblMobileDeviceProfile].[ManualDensity],[dbo].[tblMobileDeviceProfile].[HasDCU],[dbo].[tblMobileDeviceProfile].[BluetoothDCU],[dbo].[tblMobileDeviceProfile].[LogDCUActions],[dbo].[tblMobileDeviceProfile].[HasAveryHardoll],[dbo].[tblMobileDeviceProfile].[DCUComPort],[dbo].[tblMobileDeviceProfile].[DCUReadRetry],[dbo].[tblMobileDeviceProfile].[DCUDisconnectDelay],[dbo].[tblMobileDeviceProfile].[DCUCommunicationFailRestart],[dbo].[tblMobileDeviceProfile].[AveryHardollComPort],[dbo].[tblMobileDeviceProfile].[AveryHardollMeterID],[dbo].[tblMobileDeviceProfile].[ConfirmFuelCaps],[dbo].[tblMobileDeviceProfile].[VTOEnabled],[dbo].[tblMobileDeviceProfile].[EnabledInOpGauges],[dbo].[tblMobileDeviceProfile].[UseDispensingVehicleGSETrans],[dbo].[tblMobileDeviceProfile].[GSEWaitMSecForGetMeter],[dbo].[tblMobileDeviceProfile].[GSEInactiveLogoutMinutes],[dbo].[tblMobileDeviceProfile].[GSEInactiveTimeout],[dbo].[tblMobileDeviceProfile].[BarcodeInvalidWarningSeconds],[dbo].[tblMobileDeviceProfile].[DeIceBlendDefault],[dbo].[tblMobileDeviceProfile].[CommunicationTimeoutSeconds],[dbo].[tblMobileDeviceProfile].[ConnectionRetries],[dbo].[tblMobileDeviceProfile].[ConnectionRetryTimeout],[dbo].[tblMobileDeviceProfile].[ConnectionType],[dbo].[tblMobileDeviceProfile].[UpdateInterval],[dbo].[tblMobileDeviceProfile].[PingVerificationIPAddress],[dbo].[tblMobileDeviceProfile].[VehicleUpdateInterval],[dbo].[tblMobileDeviceProfile].[PresubmitDelay],[dbo].[tblMobileDeviceProfile].[VerificationIPAddress],[dbo].[tblMobileDeviceProfile].[CreatedDate],[dbo].[tblMobileDeviceProfile].[CreatedBy],[dbo].[tblMobileDeviceProfile].[UpdatedDate],[dbo].[tblMobileDeviceProfile].[UpdatedBy], [dbo].[tblMobileDeviceProfile].[_RowVersion]
            FROM [dbo].[tblMobileDeviceProfile]
            WHERE 1=2;
            
        RETURN;
    END

    IF (@sync_batch_size_tblMobileDeviceProfile IS NULL OR 
        (@sync_batch_size_tblMobileDeviceProfile IS NOT NULL AND @sync_batch_size_tblMobileDeviceProfile = 0))
    BEGIN
        SET @sync_batch_size_tblMobileDeviceProfile = 2147483647;
    END

            SELECT TOP(@sync_batch_size_tblMobileDeviceProfile) WITH TIES [MobileDeviceProfileGuid],[SiteGuid],[ProfileID],[Description],[ShowProductScreen],[GenerateTicketNumber],[ShowOperatorFieldInFlightList],[UseDefaultPrinter],[DefaultPrinter],[AdminPassword],[ShutdownHotKey],[PrinterCOMPort],[SearchType],[LoggingOption],[AllowableFailedLoginAttempts],[FuelDistributionPrecision],[MakeDefaultProfile],[VehicleID],[MonitorScreenTransitionTiming],[BypassFsrCheckOnScreenTrans],[ShowFuelUpdateCheckStatusWin],[RTDTemperatureRangeMin],[RTDTemperatureRangeMax],[DefaultTemperature],[StrictUserValidation],[VerifyFuelingEquipment],[AllowEditRequiredFuelLoad],[AllowBackAfterArrivalScreen],[AllowBackAfterTicketPrinted],[RequirePrint],[TotalFuelLoadCheck],[VolumetricThresholdValidation],[ValidateShipNumber],[AllowVTOModification],[AllowFlightGateModification],[TankPositionBalanceVerification],[TankPositionBalancePercentage],[OverrideWingBalancePercentVar],[BypassDistributionTolerance],[VehicleIDCheck],[GSEFuelMustMatch],[AllowManualMeter],[UseValidLogicGATrans],[AllowShipNumberModification],[AllowAircraftTypeModification],[AllowDestinationModification],[TicketPrinting],[AircraftTypeVerification],[Destination],[Gate],[ShipNumber],[MeterTotal],[VolumePumped],[TankCapacity],[EAStrictUserValidation],[EAVerifyFuelingEquipment],[EAAllowEditOfRequiredFuelLoad],[EAAllowBackAfterArrivalScreen],[EAAllowBackAfterTicketPrinted],[EARequirePrint],[EATotalFuelLoad],[EAVolumetricThresholdValidation],[EAValidateShipNumber],[EAAllowVTOModification],[EAAllowFlightGateModification],[EATankDiffPercentage],[EAWingBalancePercentage],[EABypassDistributionTolerance],[EAVehicleIDCheck],[EAGSEFuelMustMatch],[EAAllowManualMeter],[EAUseValidationLogicGATrans],[EAAllowShipNumberModification],[EAAllowAircraftTypeModification],[EAAllowDestinationModification],[EADestination],[EATicketPrinting],[EAAircraftType],[EAShipNumber],[EAGateNumber],[EAMeterTotal],[EAVolumePumped],[EATankCapacity],[EquipmentType],[ForeignKeyToMapEquipment],[IssueTransaction],[DefuelTransaction],[RotationTransaction],[MeterCloseout],[DeIceTransaction],[GSETransaction],[ManualConsumer],[ManualVendor],[ManualShipper],[ManualManager],[ManualSupplier],[ManualBillTo],[ManualProduct],[CloseoutConsumer],[CloseoutOwner],[CloseoutVendor],[ManualStationID],[InhibitOverridingTemperature],[ManualTemperature],[ManualDensity],[HasDCU],[BluetoothDCU],[LogDCUActions],[HasAveryHardoll],[DCUComPort],[DCUReadRetry],[DCUDisconnectDelay],[DCUCommunicationFailRestart],[AveryHardollComPort],[AveryHardollMeterID],[ConfirmFuelCaps],[VTOEnabled],[EnabledInOpGauges],[UseDispensingVehicleGSETrans],[GSEWaitMSecForGetMeter],[GSEInactiveLogoutMinutes],[GSEInactiveTimeout],[BarcodeInvalidWarningSeconds],[DeIceBlendDefault],[CommunicationTimeoutSeconds],[ConnectionRetries],[ConnectionRetryTimeout],[ConnectionType],[UpdateInterval],[PingVerificationIPAddress],[VehicleUpdateInterval],[PresubmitDelay],[VerificationIPAddress],[CreatedDate],[CreatedBy],[UpdatedDate],[UpdatedBy],_RowVersion
            FROM (
                SELECT TOP(@sync_batch_size_tblMobileDeviceProfile) WITH TIES [dbo].[tblMobileDeviceProfile].[MobileDeviceProfileGuid],[dbo].[tblMobileDeviceProfile].[SiteGuid],[dbo].[tblMobileDeviceProfile].[ProfileID],[dbo].[tblMobileDeviceProfile].[Description],[dbo].[tblMobileDeviceProfile].[ShowProductScreen],[dbo].[tblMobileDeviceProfile].[GenerateTicketNumber],[dbo].[tblMobileDeviceProfile].[ShowOperatorFieldInFlightList],[dbo].[tblMobileDeviceProfile].[UseDefaultPrinter],[dbo].[tblMobileDeviceProfile].[DefaultPrinter],[dbo].[tblMobileDeviceProfile].[AdminPassword],[dbo].[tblMobileDeviceProfile].[ShutdownHotKey],[dbo].[tblMobileDeviceProfile].[PrinterCOMPort],[dbo].[tblMobileDeviceProfile].[SearchType],[dbo].[tblMobileDeviceProfile].[LoggingOption],[dbo].[tblMobileDeviceProfile].[AllowableFailedLoginAttempts],[dbo].[tblMobileDeviceProfile].[FuelDistributionPrecision],[dbo].[tblMobileDeviceProfile].[MakeDefaultProfile],[dbo].[tblMobileDeviceProfile].[VehicleID],[dbo].[tblMobileDeviceProfile].[MonitorScreenTransitionTiming],[dbo].[tblMobileDeviceProfile].[BypassFsrCheckOnScreenTrans],[dbo].[tblMobileDeviceProfile].[ShowFuelUpdateCheckStatusWin],[dbo].[tblMobileDeviceProfile].[RTDTemperatureRangeMin],[dbo].[tblMobileDeviceProfile].[RTDTemperatureRangeMax],[dbo].[tblMobileDeviceProfile].[DefaultTemperature],[dbo].[tblMobileDeviceProfile].[StrictUserValidation],[dbo].[tblMobileDeviceProfile].[VerifyFuelingEquipment],[dbo].[tblMobileDeviceProfile].[AllowEditRequiredFuelLoad],[dbo].[tblMobileDeviceProfile].[AllowBackAfterArrivalScreen],[dbo].[tblMobileDeviceProfile].[AllowBackAfterTicketPrinted],[dbo].[tblMobileDeviceProfile].[RequirePrint],[dbo].[tblMobileDeviceProfile].[TotalFuelLoadCheck],[dbo].[tblMobileDeviceProfile].[VolumetricThresholdValidation],[dbo].[tblMobileDeviceProfile].[ValidateShipNumber],[dbo].[tblMobileDeviceProfile].[AllowVTOModification],[dbo].[tblMobileDeviceProfile].[AllowFlightGateModification],[dbo].[tblMobileDeviceProfile].[TankPositionBalanceVerification],[dbo].[tblMobileDeviceProfile].[TankPositionBalancePercentage],[dbo].[tblMobileDeviceProfile].[OverrideWingBalancePercentVar],[dbo].[tblMobileDeviceProfile].[BypassDistributionTolerance],[dbo].[tblMobileDeviceProfile].[VehicleIDCheck],[dbo].[tblMobileDeviceProfile].[GSEFuelMustMatch],[dbo].[tblMobileDeviceProfile].[AllowManualMeter],[dbo].[tblMobileDeviceProfile].[UseValidLogicGATrans],[dbo].[tblMobileDeviceProfile].[AllowShipNumberModification],[dbo].[tblMobileDeviceProfile].[AllowAircraftTypeModification],[dbo].[tblMobileDeviceProfile].[AllowDestinationModification],[dbo].[tblMobileDeviceProfile].[TicketPrinting],[dbo].[tblMobileDeviceProfile].[AircraftTypeVerification],[dbo].[tblMobileDeviceProfile].[Destination],[dbo].[tblMobileDeviceProfile].[Gate],[dbo].[tblMobileDeviceProfile].[ShipNumber],[dbo].[tblMobileDeviceProfile].[MeterTotal],[dbo].[tblMobileDeviceProfile].[VolumePumped],[dbo].[tblMobileDeviceProfile].[TankCapacity],[dbo].[tblMobileDeviceProfile].[EAStrictUserValidation],[dbo].[tblMobileDeviceProfile].[EAVerifyFuelingEquipment],[dbo].[tblMobileDeviceProfile].[EAAllowEditOfRequiredFuelLoad],[dbo].[tblMobileDeviceProfile].[EAAllowBackAfterArrivalScreen],[dbo].[tblMobileDeviceProfile].[EAAllowBackAfterTicketPrinted],[dbo].[tblMobileDeviceProfile].[EARequirePrint],[dbo].[tblMobileDeviceProfile].[EATotalFuelLoad],[dbo].[tblMobileDeviceProfile].[EAVolumetricThresholdValidation],[dbo].[tblMobileDeviceProfile].[EAValidateShipNumber],[dbo].[tblMobileDeviceProfile].[EAAllowVTOModification],[dbo].[tblMobileDeviceProfile].[EAAllowFlightGateModification],[dbo].[tblMobileDeviceProfile].[EATankDiffPercentage],[dbo].[tblMobileDeviceProfile].[EAWingBalancePercentage],[dbo].[tblMobileDeviceProfile].[EABypassDistributionTolerance],[dbo].[tblMobileDeviceProfile].[EAVehicleIDCheck],[dbo].[tblMobileDeviceProfile].[EAGSEFuelMustMatch],[dbo].[tblMobileDeviceProfile].[EAAllowManualMeter],[dbo].[tblMobileDeviceProfile].[EAUseValidationLogicGATrans],[dbo].[tblMobileDeviceProfile].[EAAllowShipNumberModification],[dbo].[tblMobileDeviceProfile].[EAAllowAircraftTypeModification],[dbo].[tblMobileDeviceProfile].[EAAllowDestinationModification],[dbo].[tblMobileDeviceProfile].[EADestination],[dbo].[tblMobileDeviceProfile].[EATicketPrinting],[dbo].[tblMobileDeviceProfile].[EAAircraftType],[dbo].[tblMobileDeviceProfile].[EAShipNumber],[dbo].[tblMobileDeviceProfile].[EAGateNumber],[dbo].[tblMobileDeviceProfile].[EAMeterTotal],[dbo].[tblMobileDeviceProfile].[EAVolumePumped],[dbo].[tblMobileDeviceProfile].[EATankCapacity],[dbo].[tblMobileDeviceProfile].[EquipmentType],[dbo].[tblMobileDeviceProfile].[ForeignKeyToMapEquipment],[dbo].[tblMobileDeviceProfile].[IssueTransaction],[dbo].[tblMobileDeviceProfile].[DefuelTransaction],[dbo].[tblMobileDeviceProfile].[RotationTransaction],[dbo].[tblMobileDeviceProfile].[MeterCloseout],[dbo].[tblMobileDeviceProfile].[DeIceTransaction],[dbo].[tblMobileDeviceProfile].[GSETransaction],[dbo].[tblMobileDeviceProfile].[ManualConsumer],[dbo].[tblMobileDeviceProfile].[ManualVendor],[dbo].[tblMobileDeviceProfile].[ManualShipper],[dbo].[tblMobileDeviceProfile].[ManualManager],[dbo].[tblMobileDeviceProfile].[ManualSupplier],[dbo].[tblMobileDeviceProfile].[ManualBillTo],[dbo].[tblMobileDeviceProfile].[ManualProduct],[dbo].[tblMobileDeviceProfile].[CloseoutConsumer],[dbo].[tblMobileDeviceProfile].[CloseoutOwner],[dbo].[tblMobileDeviceProfile].[CloseoutVendor],[dbo].[tblMobileDeviceProfile].[ManualStationID],[dbo].[tblMobileDeviceProfile].[InhibitOverridingTemperature],[dbo].[tblMobileDeviceProfile].[ManualTemperature],[dbo].[tblMobileDeviceProfile].[ManualDensity],[dbo].[tblMobileDeviceProfile].[HasDCU],[dbo].[tblMobileDeviceProfile].[BluetoothDCU],[dbo].[tblMobileDeviceProfile].[LogDCUActions],[dbo].[tblMobileDeviceProfile].[HasAveryHardoll],[dbo].[tblMobileDeviceProfile].[DCUComPort],[dbo].[tblMobileDeviceProfile].[DCUReadRetry],[dbo].[tblMobileDeviceProfile].[DCUDisconnectDelay],[dbo].[tblMobileDeviceProfile].[DCUCommunicationFailRestart],[dbo].[tblMobileDeviceProfile].[AveryHardollComPort],[dbo].[tblMobileDeviceProfile].[AveryHardollMeterID],[dbo].[tblMobileDeviceProfile].[ConfirmFuelCaps],[dbo].[tblMobileDeviceProfile].[VTOEnabled],[dbo].[tblMobileDeviceProfile].[EnabledInOpGauges],[dbo].[tblMobileDeviceProfile].[UseDispensingVehicleGSETrans],[dbo].[tblMobileDeviceProfile].[GSEWaitMSecForGetMeter],[dbo].[tblMobileDeviceProfile].[GSEInactiveLogoutMinutes],[dbo].[tblMobileDeviceProfile].[GSEInactiveTimeout],[dbo].[tblMobileDeviceProfile].[BarcodeInvalidWarningSeconds],[dbo].[tblMobileDeviceProfile].[DeIceBlendDefault],[dbo].[tblMobileDeviceProfile].[CommunicationTimeoutSeconds],[dbo].[tblMobileDeviceProfile].[ConnectionRetries],[dbo].[tblMobileDeviceProfile].[ConnectionRetryTimeout],[dbo].[tblMobileDeviceProfile].[ConnectionType],[dbo].[tblMobileDeviceProfile].[UpdateInterval],[dbo].[tblMobileDeviceProfile].[PingVerificationIPAddress],[dbo].[tblMobileDeviceProfile].[VehicleUpdateInterval],[dbo].[tblMobileDeviceProfile].[PresubmitDelay],[dbo].[tblMobileDeviceProfile].[VerificationIPAddress],[dbo].[tblMobileDeviceProfile].[CreatedDate],[dbo].[tblMobileDeviceProfile].[CreatedBy],[dbo].[tblMobileDeviceProfile].[UpdatedDate],[dbo].[tblMobileDeviceProfile].[UpdatedBy],sync.udf_GetMaxRowVersion(CT.UpdatedRowVersion,MAPCT.UpdatedRowVersion,NULL) AS '_RowVersion'
                    FROM [dbo].[tblMobileDeviceProfile]
                        INNER JOIN (SELECT [MobileDeviceProfileToSiteGuid],[MobileDeviceProfileGuid],[OwnerSiteGuid],[AssignedToSiteGuid] FROM [dbo].[udf_GetAssignedMobileDeviceProfileListForSite](@sync_context_site_guid)) data
                            ON [dbo].[tblMobileDeviceProfile].[MobileDeviceProfileGuid] = data.[MobileDeviceProfileGuid]
                        INNER JOIN [track].[tblMobileDeviceProfile] CT
                            ON CT.PK_MobileDeviceProfileGuid = [dbo].[tblMobileDeviceProfile].[MobileDeviceProfileGuid] 
                        INNER JOIN [track].[tblEntityMobileDeviceProfileToSite] MAPCT
                            ON MAPCT.PK_MobileDeviceProfileToSiteGuid = data.[MobileDeviceProfileToSiteGuid] 
                    WHERE (((CT.UpdatedRowVersion > @sync_last_received_anchor_varbinary)
                            AND (CT.UpdatedRowVersion <= @sync_new_received_anchor_varbinary)
                            AND (CT.UpdatedRowVersion > CT.InsertedRowVersion)
                            AND (CT.UpdatedContext IS NULL OR CT.UpdatedContext <> @sync_server_id_binary))   -- USE THE SERVER ID HERE SO WE DO NOT RETURN WHAT WAS JUST RECEIVED
                            OR ((MAPCT.UpdatedRowVersion > @sync_last_received_anchor_varbinary)
                            AND (MAPCT.UpdatedRowVersion <= @sync_new_received_anchor_varbinary)
                            AND (MAPCT.UpdatedRowVersion > MAPCT.InsertedRowVersion)
                            AND (MAPCT.UpdatedContext IS NULL OR MAPCT.UpdatedContext <> @sync_server_id_binary)))   -- USE THE SERVER ID HERE SO WE DO NOT RETURN WHAT WAS JUST RECEIVED
                ORDER BY [_RowVersion] ASC
            ) rs1
            ORDER BY [_RowVersion] ASC;

    SET @minValidVersion = 0;   -- This is used to detect Change Tracking cleanup
                                -- If we support this, we should add a column to SynchronizationTable
                                -- that records the MinValidVersion after change tracking information for
                                -- a table gets cleaned up.  I don't think this will be necessary.
    
    IF @minValidVersion > @sync_last_received_anchor 
        RAISERROR(N'(SIU)Time between synchronization has exceeded the maximum amount of time for table ''%s'' (MIN: %I64d, LAST: %I64d).  To avoid data corruption and old data, the client must reinitialize its local database with a current refresh from the server.', 16, 3, @sync_table_name, @minValidVersion, @sync_last_received_anchor) 
END
